'use strict';
const $=id=>document.getElementById(id), token=document.querySelector('meta[name="studio-token"]').content;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const help={
 videoAspect:['Aspect ratio','Selecting a starting image automatically matches its proportions using dimensions supported by the video model. Small rounding differences are needed for model alignment. Resolution stays within the model’s usual pixel budget. You can override this with a preset or custom dimensions.'],
 completionSound:['Completion sound','Play one short ping after each successful image, video, edit, upscale, talking-avatar or voice generation, including each job in the queue. It also works when Studio is minimized. Imports, downloads, failed jobs and cancellations stay quiet. The setting saves immediately; Test ping plays a sample even when this option is off.'],
 resources:['Resource usage','GPU shows processor activity. VRAM is graphics memory; RAM is system memory. Committed memory includes RAM and the Windows paging file. Near the committed limit, model loading can fail. GPU is NVIDIA kernel activity, sampled every second. It can be low while a model loads or the CPU prepares work, even with high VRAM usage. VRAM shows allocated memory, not processor activity. A dash means the reading is unavailable or stale.'],
 model:['Model','Choose a model and install it in Models if needed. Changing models selects recommended steps and prompt strength. Model licenses and acceptable-use terms apply.'],
 prompt:['Description or instruction','For generation, describe the full image or video. For FLUX.2 Klein and Qwen Image Edit, describe the change, such as “Change the jacket to blue.” For SDXL redraw, describe the whole desired result. The starting image is image 1; extra references are images 2 and 3.'],
 negative:['Negative prompt','Describe details to avoid. Z-Image-Turbo and distilled FLUX.2/FLUX 3 Klein use guidance 1 and ignore negative prompts.'],
 dimensions:['Output dimensions','Images need multiples of 64, from 256 to 1536 pixels. Wan 2.2 needs multiples of 32; LTX-2 needs multiples of 64. Larger sizes use more memory. Editor sources are resized to these dimensions.'],
 seed:['Seed','The displayed seed is used for the next job. Leave empty for random. Reusing the seed with the same model and settings helps reproduce a result. Allowed range: 0–9007199254740991.'],
 randomizeSeed:['New seed for each job','After a new job is added to the queue, prepares a fresh random seed for the next job. This lets you queue different variations immediately. Turn off to keep a fixed seed for comparisons or reproducing a result. Already queued jobs, retries and saved results keep their exact seeds.'],
 flux3Access:['FLUX 3 access','Open the official model page, sign in to Hugging Face and review its access conditions. Once access is granted, enter a read token from that account in Settings. The token is used only for this install and is not saved. The model files and separate compatible engine install together.'],
 steps:['Steps','More denoising steps take longer. FLUX 3 Image Klein starts at 16 steps. Start with 8 for Z-Image-Turbo and DreamShaper Turbo, 4 for FLUX.2 Klein, 28 for SDXL, and 40 for Qwen. LTX-2 uses its fixed 8-step recipe.'],
 cfg:['Prompt strength','CFG controls how strongly sampling follows the description. Z-Image-Turbo, distilled FLUX.2/FLUX 3 Klein and LTX-2 use a fixed value of 1.'],
 memory:['Memory mode','Low VRAM moves more work into system RAM and can be slower. Large models still need enough RAM and committed memory. The app does not change your paging file.'],
 source:['Starting image','Choose from the library or import PNG, JPEG or WebP up to 25 MB and 25 megapixels. Imports, edits and extracted video frames are saved as separate library images.'],
 references:['Reference images','FLUX.2 Klein and Qwen Image Edit accept the starting image plus up to two extra references in this studio. Refer to image 1, image 2 and image 3 in your instruction. FLUX 3 accepts nine extra references (ten images total); refer to the starting image as <ref_image_0> and extras as <ref_image_1> through <ref_image_9>. Describe the complete desired edited result. SDXL redraw does not support extra references.'],
 mask:['Painted area','Paint the area to change. SDXL uses masked denoising. Instruction models edit the full image, then only the painted region is composited onto the resized original. Use a smaller brush to refine boundaries.'],
 brush:['Brush size','Brush diameter in output pixels. Paint adds the area to change; Erase removes it. Undo restores the previous stroke. Clear removes the entire mask.'],
 strength:['Redraw strength','SDXL only. Smaller values retain more of the starting image; larger values change more. Range: greater than zero to 1. Instruction editing uses its full sampling recipe.'],
 crop:['Crop and resize','X and Y are the crop’s top-left corner in original image pixels. Crop width and height define its area. Output dimensions resize that area. Save creates a separate library image using the CPU.'],
 aspect:['Keep aspect ratio','Changing the resize width or height adjusts the other dimension to the crop’s ratio. Uncheck to stretch to a specific size.'],
 frames:['Video length','Up to 481 frames. Duration is frames divided by FPS. Wan needs 4n+1 frames; LTX-2 needs 8n+1. Longer clips need much more memory and time, and may lose consistency beyond typical short training clips. This is one generation, not stitched video extension.'],
 fps:['Playback FPS','Frames per second. Lower FPS plays the same frames more slowly; it does not add motion frames. LTX-2 also uses FPS for audio and motion conditioning.'],
 mode:['Video input','Text to Video starts from a description. Image to Video starts from an image. NSFW Wan 1.3B E14 is text-only; use Wan 2.2 or LTX-2 to animate an image.'],
 audio:['LTX-2 audio','Generate audio together with LTX-2 video. Other video models export silent MP4s.'],
 shift:['Motion shift','Wan’s sampling shift changes the noise schedule and can affect motion and detail. Default: 8. LTX-2 uses its own fixed recipe.'],
 sampler:['Sampler','Wan’s denoising method. UniPC is the default; Euler and DPM++ 2M are alternatives. Image models and LTX-2 use their own recipes.'],
 scheduler:['Noise schedule','Wan’s sequence of noise levels. Simple is the default. Changing it changes the result even with the same seed.'],
 output:['Library folder','Images and Videos are separate subfolders here. Generated, imported, edited and enhanced images go in Images; generated and enhanced videos go in Videos. Image and video metadata JSON files are kept separately in Metadata. Changing this setting affects future files; the library keeps access to previous locations.'],
 packs:['Model installation','Downloads the model, encoders and VAE with pinned revisions and SHA-256 checks. Identical model files, text encoders and VAEs are reused and counted once. Different fine-tuned checkpoints still need their own weights. Canceled downloads can resume. Qwen’s large models use system RAM offloading on 16 GB cards.'],
 access:['Hugging Face token','Optional read token for gated or private downloads. Used only for the current operation; not saved. Public model packs do not need a token.'],
 loras:['LoRAs','Install standard .safetensors adapters for the selected base model. Enable up to eight and save their strengths. Assignment to a model library does not prove compatibility: check the author’s exact base model, trigger words and recommended recipe. Specialized control or acceleration adapters can need additional workflow changes.'],
 loraTarget:['Target model','Choose the model these adapters belong to. SDXL models share their file library but keep separate enabled selections. Other models have separate libraries. Existing Wan 1.3B adapters stay available.'],
 loraStrength:['Model strength','How strongly the adapter changes the diffusion model. 1 is normal, smaller values reduce the effect, 0 has no effect, and negative values reverse it when supported. Follow the author’s recommended value.'],
 loraClip:['Text encoder strength','SDXL and legacy Wan 1.3B only. Controls the adapter’s text-encoder weights independently from model strength. If the adapter has no text-encoder weights this setting has no effect. Transformer-only adapters leave the text encoder unchanged.'],
 loraSites:['Download sites','CivitAI opens its LoRA catalog. Hugging Face opens a LoRA search for the selected base model. Both open in your regular browser in the desktop app. Download a .safetensors file, then import it here. CivitAI may require signing in; this app does not store a CivitAI API key. A specific Hugging Face file link can also be downloaded directly below.'],
 frame:['Video frame','Play or scrub to choose a timestamp. Save frame creates a PNG library image on the CPU and sends it to the selected tool. The MP4 stays in the library.'],
 search:['Library search','Search filenames or stored prompts. Filters and pagination cover the entire library. Square thumbnails are cropped previews; original dimensions are preserved.'],
 libraryFolder:['Open containing folder','Opens Windows File Explorer at this image or video’s saved location and selects the file. Works for imported files and older output folders, even while a generation is running.'],
 imageZoom:['Fullscreen image viewer','Scroll the mouse wheel to zoom toward the pointer. Drag to move around a zoomed image. Fit shows the whole image; 100% shows its original pixel dimensions. Use + and − to zoom, or Escape / × to return to the details page. Viewing does not modify the saved image.']
};
function q(key){return `<button class="help" type="button" data-help="${key}" aria-label="Explain ${esc(help[key][0])}">?</button>`}
function f(id,label,control,key){return `<div class="field"><label for="${id}">${label} ${q(key)}</label>${control}</div>`}
function inp(id,value='',type='text',attrs=''){return `<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}>`}
function sel(id,options){return `<select id="${id}">${options.map(x=>`<option value="${esc(x[0])}">${esc(x[1])}</option>`).join('')}</select>`}
function num(id,v,min,max,step=1){return inp(id,v,'number',`min="${min}" max="${max}" step="${step}"`)}
function sizes(p,video=false){return `<div class="two">${f(p+'width','Width',num(p+'width',video?832:1024,video?144:256,video?1024:1536,video?16:64),'dimensions')}${f(p+'height','Height',num(p+'height',video?480:1024,video?144:256,video?1024:1536,video?16:64),'dimensions')}</div>`}
function seedControls(p){return `${f(p+'seed','Seed',inp(p+'seed','','text','inputmode="numeric" placeholder="Empty = random"'),'seed')}<label class="check seed-option"><input id="${p}randomize_seed" type="checkbox" checked>New seed for each job ${q('randomizeSeed')}</label>`}
function randomSeed(previous=''){const bits=new Uint32Array(2);let seed;do{crypto.getRandomValues(bits);seed=(bits[0]&0x1fffff)*4294967296+bits[1];}while(String(seed)===String(previous));return String(seed);}
function advanceSeed(p,submitted){const field=$(p+'seed');if($(p+'randomize_seed').checked&&field.value===String(submitted??''))field.value=randomSeed(submitted);}
function initializeSeeds(){for(const p of ['i','e','v','ui-'])if($(p+'randomize_seed').checked)$(p+'seed').value=randomSeed($(p+'seed').value);}
function advanced(p,video=false){return `<details><summary>Advanced settings</summary>${f(p+'negative','Negative prompt',`<textarea id="${p}negative" maxlength="10000" style="min-height:65px">blurry, low quality, artifacts, watermark</textarea>`,'negative')}<div class="two">${f(p+'steps','Steps',num(p+'steps',video?30:8,1,video?80:60),'steps')}${f(p+'cfg','Prompt strength',num(p+'cfg',video?6:2,1,15,.1),'cfg')}</div>${seedControls(p)}${video?`<div class="two">${f('vshift','Motion shift',num('vshift',8,1,15,.1),'shift')}${f('vfps','Playback FPS',num('vfps',16,8,30),'fps')}</div><div class="two">${f('vsampler','Sampler',sel('vsampler',[['uni_pc','UniPC'],['euler','Euler'],['dpmpp_2m','DPM++ 2M']]),'sampler')}${f('vscheduler','Schedule',sel('vscheduler',[['simple','Simple'],['normal','Normal'],['sgm_uniform','SGM uniform']]),'scheduler')}</div>`:''}${f(p+'memory','Memory mode',sel(p+'memory',[['auto','Automatic'],['low','Low VRAM']]),'memory')}</details>`}
function sourceControls(p){return `<label>Starting image ${q('source')}</label><div id="${p}source" class="notice">No image selected.</div><div class="row"><button type="button" data-pick="${p}">From library</button><button type="button" data-import="${p}">Import image</button></div>`}
const empty=`<div class="empty"><svg width="70" height="70" viewBox="0 0 70 70" fill="none" aria-hidden="true"><rect x="8" y="8" width="54" height="54" rx="7" stroke="currentColor"/><path d="m10 50 17-19 15 17 9-10 10 12M27 23h.01" stroke="currentColor" stroke-width="2"/></svg>Your result appears here.<br>Created media is saved in the library.</div>`;
const pages={images:['Images','Generate images from text, then send them to the editor or video generator.'],editor:['Image Editor','Edit with instructions, paint an area to change, add references, or crop and resize.'],video:['Video','Create video from text or animate an image with Wan 2.2 or LTX-2.'],library:['Library','Browse saved images and videos. Open an item or send it to another tool.'],models:['Models','Install image, editing and video models, and check which are ready to use.'],loras:['LoRAs','Install adapters, choose their target model, and save which ones generation uses.'],settings:['Settings','Choose output storage, repair the base runtime, and open your media or logs.']};
