<section id="page-images" class="page"><div class="workspace"><form id="image-form" class="controls"><div class="control-scroll">${f('imodel','Image model','<select id="imodel"></select>','model')}<span id="i-ready" class="model-state"></span>${f('iprompt','Image description','<textarea id="iprompt" required maxlength="10000" placeholder="Describe your image…"></textarea>','prompt')}${f('ishape','Image shape',sel('ishape',[['1024x1024','Square · 1024 × 1024'],['1152x768','Landscape · 1152 × 768'],['768x1152','Portrait · 768 × 1152'],['512x512','Small · 512 × 512'],['custom','Custom dimensions']]),'dimensions')}<div id="i-size" hidden>${sizes('i')}</div>${advanced('i')}</div><div class="control-footer"><button class="primary" data-job>Generate image</button></div></form><div class="preview"><div class="preview-heading"><span>Image preview</span><span>PNG</span></div><div id="image-preview" class="preview-stage">${empty}</div><div id="image-actions" class="preview-actions" hidden></div></div></div></section>
