$('page-settings').querySelector('.settings-grid').insertAdjacentHTML('beforeend',`<section class="notification-settings"><h2>Notifications</h2><label class="check"><input type="checkbox" id="completion-sound" checked>Play a ping when generation completes ${q('completionSound')}</label><p>Play a short sound after each successful generation, including queued jobs.</p><div class="row" style="margin-top:12px"><button type="button" id="test-completion-sound">Test ping</button><small id="sound-status" role="status">Changes save immediately.</small></div></section>`);
help.attention=['Attention acceleration','SageAttention uses the Sage-style INT8 kernels already bundled with Comfy Kitchen. It can speed up supported image and video generation. PyTorch is used automatically if the kernel is unavailable or rejects an input. Non-finite results fall back to PyTorch; CUDA memory errors still stop the job. Quantization can change output, and speed depends on the model and memory offloading. This setting applies to the next queued job; it does not interrupt the current one. Dedicated Talking Avatar, Voice and RTX video enhancement engines keep their own settings.'];
help.attentionCheck=['Check and enable SageAttention','Runs a tiny attention math check using your GPU, without downloading models or generating an image or video. If it passes, SageAttention is enabled for subsequent generations. The check is only available when the app is idle.'];
$('page-settings').querySelector('.settings-grid>section').insertAdjacentHTML('beforeend',`<div class="acceleration-settings"><h2>Generation acceleration</h2>${f('attention-mode','Attention backend',sel('attention-mode',[['pytorch','PyTorch · standard'],['sage','SageAttention · automatic fallback']]),'attention')}<button type="button" id="check-attention" data-job>Check &amp; enable SageAttention</button>${q('attentionCheck')}<p id="attention-status" class="notice" role="status">No generation engine is running.</p><small>Changes apply to the next generation. A compatibility check does not measure video render speed.</small></div>`);
$('page-settings').querySelector('.settings-grid>section').append(document.querySelector('.notification-settings'));
function renderAttention(){
 const info=state?.attention;if(!info)return;
 const select=$('attention-mode');if(document.activeElement!==select&&!select.disabled)select.value=info.preference||'pytorch';
 const names={idle:'No engine running',starting:'Starting generation engine',sage_ready:'SageAttention selected; waiting for generation',sage:'SageAttention in use',pytorch_fallback:'PyTorch fallback',pytorch:'PyTorch'};
 const checked=info.check?.checked_at?(info.check.available?'Compatibility check passed. ':'Compatibility check: '+(info.check.reason||'unavailable')+'. '):'Compatibility has not been checked. ';
 $('attention-status').textContent='Next generation: '+(info.preference==='sage'?'SageAttention':'PyTorch')+'. '+checked+(info.engine_running?(names[info.active]||info.active)+'. '+(info.reason||''):'No generation engine is running.');
}
async function saveAttentionMode(){
 const select=$('attention-mode'),mode=select.value,previous=state?.settings.attention||'pytorch';select.disabled=true;
 try{await action('/api/settings',{attention:mode});if(state?.settings)state.settings.attention=mode;if(state?.attention)state.attention.preference=mode;notify('Attention preference saved for the next generation.');}
 catch{select.value=previous;}
 finally{select.disabled=false;renderAttention();}
}
$('attention-mode').onchange=saveAttentionMode;
$('check-attention').onclick=()=>action('/api/attention/check',{enable:true}).catch(()=>{});
function showPage(id){if(!pages[id])return;current=id;for(const key in pages)$('page-'+key).hidden=key!==id;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$('page-title').textContent=pages[id][0];$('page-description').textContent=pages[id][1];if(id==='library')loadLibrary();if(id==='editor')requestAnimationFrame(fitCanvas)}
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,8000)}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Wan-Token':token,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await response.json();if(!response.ok)throw Error(result.error||'Operation failed.');return result}
