function sourceFor(target){return target==='v'?'video':target==='e'?'editor':target}
let videoSourceRevision=0,videoSourceSave=Promise.resolve();
function selectVideoSource(item,remember=true){
 videoSource=item;videoSourceRevision++;
 if(item){
  if($('vmodel').value==='wan13'){$('vmodel').value='wan22';videoModelChanged();}
  $('vmode').value='image';$('video-source-controls').hidden=false;adaptVideoAspect(item);
 }
 if(!remember)return;
 const id=item?.id||'';
 videoSourceSave=videoSourceSave.catch(()=>{}).then(()=>api('/api/settings',{video_source_image:id})).catch(error=>notify('Image selected, but the selection could not be saved: '+error.message));
}
async function restoreVideoSource(){
 const id=state?.settings.video_source_image??state?.settings.options?.source_image;
 if(!id||videoSource)return;
 const revision=videoSourceRevision;
 try{
  const item=state.images.find(image=>image.id===id)||(await api('/api/library/'+encodeURIComponent(id))).item;
  if(videoSourceRevision!==revision||videoSource)return;
  if(!item||item.id!==id||item.media_type==='video')throw Error('Starting image unavailable');
  selectVideoSource(item,false);renderSources();
 }catch(error){if(videoSourceRevision===revision&&!videoSource)notify('The saved starting image is unavailable. Choose another image from Library.');}
}
let sourceImportBusy=false;
function updateImageImportButtons(){document.querySelectorAll('[data-import]').forEach(button=>button.disabled=sourceImportBusy||(button.dataset.import==='reference'&&references.length>=referenceLimit())||button.dataset.referenceFull==='true');}
async function importFile(file,target){
 if(!file)return;if(sourceImportBusy){notify('Wait for the current image import to finish.');return;}
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>25*1024**2){notify('Choose PNG, JPEG or WebP under 25 MB.');return;}
 const destination=sourceFor(target);sourceImportBusy=true;updateImageImportButtons();
 try{
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('The selected image could not be read. Choose it again or try another file.'));reader.onabort=()=>reject(Error('Image import cancelled.'));reader.readAsDataURL(file);});
  const result=await api('/api/images/import-source',{name:file.name,data});
  if(destination==='library'){showPage('library');}else sendImage(result.item,destination);
 }catch(error){notify(error.message);}finally{sourceImportBusy=false;updateImageImportButtons();}
}
function libraryControls(picker){const p=picker?'pick':'lib';return `<div class="library-tools"><input id="${p}-search" placeholder="Search filenames or prompts…" aria-label="Search library">${sel(p+'-type',picker?[['image','Images']]:[['all','All media'],['image','Images'],['video','Videos']])}${q('search')}${picker?'':'<button data-import="library">Import image</button>'}</div><div class="library-grid" id="${p}-grid"></div><div class="pagination"><button id="${p}-previous">← Previous</button><span id="${p}-count"></span><button id="${p}-next">Next →</button></div>`}
