function thumbnails(container,items){
 if(container.thumbnailRun)clearTimeout(container.thumbnailRun.timer);
 const run={pending:new Map(),timer:null},records=new Map(items.map(x=>[x.id,x]));container.thumbnailRun=run;
 const active=()=>container.thumbnailRun===run&&container.isConnected&&(container.id==='lib-grid'?current==='library':container.id==='cv-library'?current==='canvas':$('library-dialog').open);
 function schedule(delay=200){if(!run.timer&&run.pending.size&&active())run.timer=setTimeout(refresh,delay);}
 function display(img,item){
  if(item.thumbnail?.status==='unavailable'){img.classList.remove('thumb-pending');img.alt='Preview unavailable';return;}
  if(item.thumbnail?.status==='ready'){img.src=thumbURL(item);return;}
  img.classList.add('thumb-pending');img.alt='Preparing preview…';run.pending.set(item.id,img);
 }
 async function refresh(){
  run.timer=null;if(!active()||!run.pending.size)return;
  try{
   const statuses=await api('/api/thumbnails?ids='+encodeURIComponent([...run.pending.keys()].join(',')));
   if(!active())return;
   for(const [id,img] of [...run.pending]){const item=records.get(id);item.thumbnail=statuses[id]||{status:'unavailable'};if(item.thumbnail.status!=='pending')run.pending.delete(id);display(img,item);}
   schedule(350);
  }catch{schedule(1500);}
 }
 container.querySelectorAll('img[data-thumb]').forEach(img=>{
  const item=records.get(img.dataset.thumbnailId);if(!item)return;
  let failures=0;
  img.onload=()=>{img.classList.remove('thumb-pending');img.alt=item.name;};
  img.onerror=()=>{if(!active())return;img.removeAttribute('src');img.classList.remove('thumb-pending');img.alt='Preview unavailable';if(++failures<=3){run.pending.set(item.id,img);schedule(350);}};
  display(img,item);
 });
 schedule();
}
