function selectedLoras(){const textEncoder=loraInfo($('lora-target').value)?.text_encoder;return [...document.querySelectorAll('.lora-row')].filter(row=>row.querySelector('[type=checkbox]').checked).map(row=>({name:row.querySelector('[type=checkbox]').dataset.name,strength:Number(row.querySelector('.lora-strength').value),...(textEncoder?{strength_clip:Number(row.querySelector('.lora-clip').value)}:{})}))}
