function renderLoras(force=false){if(!$('lora-target').value)return;const model=$('lora-target').value,info=loraInfo(model);const available=state.loras.filter(x=>x.models?x.models.includes(model):model==='wan13');const signature=JSON.stringify([model,available,savedLoras(model)]);if(!force&&signature===loraSignature){renderLoraSummaries();return}loraSignature=signature;const selected=loraDrafts[model]||savedLoras(model);$('lora-guidance').textContent=info?.guidance||'Check the adapter’s exact base model.';$('civitai-loras').href=info?.civitai_url||'https://civitai.com/models?types=LORA';$('hf-loras').href=info?.hf_url||'https://huggingface.co/models?other=lora';$('lora-list-title').textContent=`${available.length} installed · ${info?.name||model}`;$('lora-list').innerHTML=available.length?available.map((x,i)=>{const saved=selected.find(y=>y.name===x.name);return `<div class="lora-row"><input type="checkbox" id="lora-${i}" data-name="${esc(x.name)}" ${saved?'checked':''} aria-label="Enable ${esc(x.display_name||x.name)}"><div class="lora-name"><label for="lora-${i}">${esc(x.display_name||x.name)} ${q('loras')}</label><small>${(x.size/1024**2).toFixed(1)} MB${x.declared_base?' · File metadata: '+esc(x.declared_base):' · Check author’s base model'}</small></div><div>${f('lora-model-'+i,'Model strength',num('lora-model-'+i,saved?.strength??1,-2,2,.01),'loraStrength').replace('<input ','<input class="lora-strength" ')}</div>${info?.text_encoder?`<div>${f('lora-text-'+i,'Text encoder',num('lora-text-'+i,saved?.strength_clip??saved?.strength??1,-2,2,.01),'loraClip').replace('<input ','<input class="lora-clip" ')}</div>`:''}</div>`}).join(''):'<p class="notice">No adapters installed for this model. Import a matching file or use the download links.</p>';$('lora-list').classList.toggle('with-text-encoder',!!info?.text_encoder);$('lora-dirty').hidden=loraSelectionKey(model,selected)===loraSelectionKey(model,savedLoras(model));lastLoraModel=model;renderLoraSummaries();}
