 const gb=n=>(n/1024**3).toFixed(1),activity=g?.percent;
 const items=[['GPU',activity,activity!=null?`${Math.round(activity)}%`:'—'],['VRAM',g?.total?100*g.used/g.total:null,g?.total?`${gb(g.used)} / ${gb(g.total)} GB`:'—'],['RAM',m?.percent,m?`${gb(m.used)} / ${gb(m.total)} GB`:'—'],['Commit',m?100*m.commit_used/m.commit_limit:null,m?`${gb(m.commit_used)} / ${gb(m.commit_limit)} GB`:'—']];
