function initialize(){const imagePacks=state.packs.filter(p=>p.kind==='image'),editorPacks=state.packs.filter(p=>p.editing&&!p.faceswap);for(const [id,items] of [['imodel',imagePacks],['emodel',editorPacks]])$(id).innerHTML=items.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');$('lora-target').innerHTML=state.lora_models.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('lora-target').value=state.settings.options?.model||'wan13';lastLoraModel=$('lora-target').value;$('imodel').value=state.settings.image_options?.model||'zimage';$('emodel').value=state.settings.edit_options?.model||'fluxklein';applyModel('i');applyModel('e');fill('i',state.settings.image_options);fill('e',state.settings.edit_options);fill('v',state.settings.options);videoModelChanged(false);for(const p of ['i','v']){const shape=$(p+'width').value+'x'+$(p+'height').value,known=[...$(p+'shape').options].some(o=>o.value===shape);$(p+'shape').value=known?shape:'custom';$(p+'-size').hidden=known;}const frames=String(state.settings.options?.frames||49);if([...$('vframes').options].some(o=>o.value===frames))$('vframes').value=frames;else{$('vframes').value='custom';$('vframecount').value=frames;$('v-custom-frames').hidden=false}$('vaudio').checked=state.settings.options?.audio!==false;$('output').value=state.settings.output;$('completion-sound').checked=state.settings.completion_sound!==false;$('gpu-name').textContent=state.gpu.name;$('brand-version').textContent='v'+state.version;$('paths').textContent='Studio data: '+state.root;updateAvailability();updateDuration();renderSources();initialized=true;restoreVideoSource();renderLoraSummaries();}
