$('import-file').onchange=e=>{importFile(e.target.files[0],importTarget);e.target.value=''};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)showPage(b.dataset.page);if(b.dataset.loraFor)openLoras($(b.dataset.loraFor+'model').value);if(b.dataset.help){const [title,copy]=help[b.dataset.help];$('help-title').textContent=title;$('help-copy').textContent=copy;$('help-dialog').showModal()}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.hasAttribute('data-clear-video-source'))clearVideoSource();if(b.dataset.pick)openPicker(b.dataset.pick);if(b.dataset.import){importTarget=b.dataset.import;$('import-file').click()}if(b.dataset.removeRef!==undefined){references.splice(Number(b.dataset.removeRef),1);renderSources()}});
$('select-image-packs').onclick=()=>{document.querySelectorAll('.pack-check:not(:disabled)').forEach(e=>e.checked=!e.closest('.pack').hidden&&['image','editor'].includes(pack(e.value)?.kind));downloadEstimate()};$('install-selected').onclick=async()=>{const keys=[...document.querySelectorAll('.pack-check:checked')].map(x=>x.value);if(!keys.length){notify('Select at least one model.');return}await action('/api/packs/install',{packs:keys,token:$('access-token').value}).catch(()=>{});$('access-token').value=''};
$('install-runtime').onclick=async()=>{await action('/api/install',{token:$('access-token').value}).catch(()=>{});$('access-token').value=''};$('cancel').onclick=()=>action('/api/cancel').catch(()=>{});$('release').onclick=()=>action('/api/release').catch(()=>{});$('log-toggle').onclick=()=>$('log-dialog').showModal();
$('save-settings').onclick=()=>action('/api/settings',{output:$('output').value}).then(()=>notify('Library folder saved.')).catch(()=>{});$('pick-output').onclick=()=>api('/api/pick-folder',{}).then(x=>{if(x.path)$('output').value=x.path}).catch(e=>notify(e.message));
async function saveCompletionSound(){
 const input=$('completion-sound'),enabled=input.checked,previous=state?.settings.completion_sound!==false;input.disabled=true;
 try{await action('/api/settings',{completion_sound:enabled});if(state?.settings)state.settings.completion_sound=enabled;$('sound-status').textContent=enabled?'Completion ping enabled.':'Completion ping muted.';}
 catch{input.checked=previous;}
 finally{input.disabled=false;}
}
$('completion-sound').onchange=saveCompletionSound;
$('test-completion-sound').onclick=async()=>{const button=$('test-completion-sound');button.disabled=true;try{await action('/api/notifications/test',{});$('sound-status').textContent='Ping played.';}catch{}finally{button.disabled=false;}};
for(const kind of ['videos','images','logs','loras'])$('open-'+kind).onclick=()=>{if(kind==='videos'&&window.chrome?.webview)window.chrome.webview.postMessage('open-videos');else action('/api/open-folder',{kind,...(kind==='loras'?{model:$('lora-target').value}:{})}).catch(()=>{})};
$('import-loras').onclick=()=>{if(window.chrome?.webview)window.chrome.webview.postMessage('import-loras:'+$('lora-target').value);else notify('Local LoRA imports are available in the desktop app. You can also paste a Hugging Face file link.');};
$('download-lora').onclick=async()=>{await action('/api/loras/download',{url:$('lora-url').value,token:$('lora-token').value,model:$('lora-target').value}).catch(()=>{});$('lora-token').value=''};$('save-loras').onclick=async()=>{const model=$('lora-target').value;try{await action('/api/loras/select',{model,loras:selectedLoras()});delete loraDrafts[model];state=await api('/api/state');renderLoras(true);notify('LoRA selection saved for '+loraInfo(model).name+'.')}catch{}};
function fullscreen(){if(window.chrome?.webview)window.chrome.webview.postMessage('toggle-fullscreen');else if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen().catch(()=>notify('Maximize the window to use more space.'))}$('fullscreen').onclick=fullscreen;document.addEventListener('keydown',e=>{if(e.key==='F11'){e.preventDefault();fullscreen()}else if(e.key==='Escape'&&window.chrome?.webview){window.chrome.webview.postMessage('exit-fullscreen')}});new ResizeObserver(()=>requestAnimationFrame(fitCanvas)).observe($('canvas-space'));
for(const id of ['page-editor','page-video','page-images']){const area=$(id);area.ondragover=e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();area.classList.add('drop-active')}};area.ondragleave=e=>{if(!area.contains(e.relatedTarget))area.classList.remove('drop-active')};area.ondrop=e=>{e.preventDefault();area.classList.remove('drop-active');importFile(e.dataTransfer.files[0],id==='page-video'?'video':'editor')}}
window.addEventListener('unhandledrejection',e=>{e.preventDefault();notify(e.reason?.message||String(e.reason))});showPage('images');poll();
